SCENE = "SC['3.12.06']=function(t,K){\n  var HD='CHAPTER 12 · EUCLID\\'S COMPASS',PIN='#6B7280';\n  function poly(V,op,col,fill){S('polygon',{points:V.map(function(p){return p.join(',');}).join(' '),fill:fill||'none',stroke:col||NAVY,'stroke-width':8,'stroke-linejoin':'round',opacity:op});}\n  if(t<K.names-0.3){head('','');owl(1000,380,150,t);book(t,0.1,'sb-byrne-quads.jpg','CHAPTER 12 · LESSON 6','Properties of Quadrilaterals','Alexandria, about 300 BC');return;}\n  if(t<K.roman-0.3){head(HD,'Euclid\\'s names for four-sided shapes');owl(null);var o=fade(t,K.names-0.3,K.roman-0.3);\n    pic('sb-byrne-quads.jpg',120,96,520,520,1+0.03*(t-K.names),.5,.5,o);\n    if(t>=K.square-0.3){poly([[760,180],[880,180],[880,300],[760,300]],o*ramp(t,K.square-0.3,0.4));label(820,340,'square',o*ramp(t,K.square-0.3,0.4),NAVY,26);}\n    if(t>=K.oblong-0.3){poly([[940,200],[1160,200],[1160,290],[940,290]],o*ramp(t,K.oblong-0.3,0.4));label(1050,340,'oblong',o*ramp(t,K.oblong-0.3,0.4),NAVY,26);}\n    if(t>=K.rhombus-0.3){poly([[900,400],[980,470],[900,540],[820,470]],o*ramp(t,K.rhombus-0.3,0.4));label(1090,480,'rhombus',o*ramp(t,K.rhombus-0.3,0.4),NAVY,26);}\n    return;}\n  if(t<K.today-0.3){head(HD,'A Roman floor of rhombuses');owl(null);var o2=fade(t,K.roman-0.3,K.today-0.3);\n    pic('sb-herculaneum-rhombi.jpg',190,100,900,520,1+0.02*(t-K.roman),.4,.5,o2);\n    if(t>=K.rhombuses-0.3)label(640,580,'marble rhombuses, Herculaneum',ramp(t,K.rhombuses-0.3,0.4)*o2,GREEN,28);return;}\n  if(t<K.family-0.4){head(HD,'Stretch a band into four-sided shapes');owl(null);var o3=ramp(t,K.today-0.3,0.5);\n    for(var y=0;y<7;y++)for(var x=0;x<9;x++)S('circle',{cx:300+x*85,cy:120+y*75,r:6,fill:PIN,opacity:o3});\n    var k=ramp(t,K.stretch-0.2,1.4),a=[300+2*85,120+1*75],b=[300+6*85,120+1*75],c=[300+(6+2*k)*85,120+5*75],d=[300+1*85,120+5*75];\n    poly([a,b,c,d],o3,'#6B46C1','rgba(107,70,193,.14)');return;}\n  head(HD,'Every shape has a family');owl(null);var o4=ramp(t,K.family-0.4,0.6);\n  var nodes=[[640,170,'quadrilateral'],[640,280,'trapezoid'],[640,390,'parallelogram'],[500,500,'rectangle'],[780,500,'rhombus'],[640,600,'square']];\n  [[0,1],[1,2],[2,3],[2,4],[3,5],[4,5]].forEach(function(e,i){var A=nodes[e[0]],B=nodes[e[1]];S('line',{x1:A[0],y1:A[1]+22,x2:B[0],y2:B[1]-22,stroke:'#8792A8','stroke-width':4,opacity:o4*ramp(t,K.family-0.2+i*0.12,0.3)});});\n  nodes.forEach(function(n,i){label(n[0],n[1],n[2],o4*ramp(t,K.family-0.3+i*0.15,0.3),NAVY,24);});\n};\n"
CUE = " '3.12.06':function(){return{names:wt(/^names$/,0),square:wt(/^square$/),oblong:wt(/^oblong$/),rhombus:wt(/^rhombus$/),roman:wt(/^Roman$/),rhombuses:wt(/^rhombuses$/),today:wt(/^Today$/),stretch:wt(/^stretch$/),family:wt(/^family$/)};},\n"
if "SC['3.12.06']=function" in s: print('already'); sys.exit()
